G = list(range(8))
H = [0, 4]
def add8(a, b):
    return (a + b) % 8
def is_subgroup(S):
    S = set(S)
    if not S:
        return False
    if 0 not in S:
        return False
    for a in S:
        if (-a) % 8 not in S:
            return False
    for a in S:
        for b in S:
            if add8(a, b) not in S:
                return False
    return True
subgroups = []
for mask in range(1, 1 << 8):
    S = {i for i in range(8) if (mask >> i) & 1}
    if is_subgroup(S):
        subgroups.append(sorted(S))
print(len(G))
print(len(H))
print(len(subgroups))
